import boto3


def decrypt_payload(ciphertext, config=None):
    config = config or {}
    client = boto3.client("kms", region_name=config.get("region"))
    response = client.decrypt(CiphertextBlob=ciphertext["ciphertext"])
    return {"plaintext": response["Plaintext"].decode()}

import boto3


def envelope_encrypt(data, config=None):
    config = config or {}
    client = boto3.client("kms", region_name=config.get("region"))
    data_key = client.generate_data_key(KeyId=config["key_id"], KeySpec='AES_256')
    encrypted_data_key = data_key['CiphertextBlob']
    plaintext_data_key = data_key['Plaintext']
    ciphertext = client.encrypt(KeyId=config["key_id"], Plaintext=data)['CiphertextBlob']
    return {
        'encrypted_data_key': encrypted_data_key,
        'ciphertext': ciphertext,
        'plaintext_data_key': plaintext_data_key
    }

import boto3


def sign_or_verify_key(payload, config=None):
    config = config or {}
    client = boto3.client("kms", region_name=config.get("region"))
    if 'message' in payload and 'signature' in payload:
        response = client.verify(KeyId=config['key_id'], Message=payload['message'], Signature=payload['signature'])
        return {'valid': response['SignatureValid']}
    elif 'message' in payload:
        response = client.sign(KeyId=config['key_id'], Message=payload['message'])
        return {'signature': response['Signature']}
    else:
        raise ValueError('Invalid payload')

