import boto3


def get_security_client(service_name, region=None):
    region = region or os.getenv('AWS_DEFAULT_REGION')
    return boto3.client(service_name, region_name=region)


def get_config():
    return {
        'region': os.getenv('AWS_DEFAULT_REGION'),
        'key_id': os.getenv('AWS_KMS_KEY_ID')
    }

from typing import Dict, Any


def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'plaintext': payload.get('plaintext', '').encode()
    }


def normalize_response(response: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'ciphertext': response.get('CiphertextBlob', b'')
    }

import boto3


def key_usage_summary(config=None):
    config = config or {}
    client = boto3.client('kms', region_name=config.get('region'))
    response = client.list_keys()
    key_usage = []
    for key in response['Keys']:
        key_id = key['KeyId']
        key_usage.append({
            'key_id': key_id,
            'usage': client.describe_key(KeyId=key_id)['KeyMetadata']['KeyUsage']
        })
    return key_usage

import re


def payload_safety(plaintext):
    unsafe_patterns = [
        re.compile(r'<script.*?>.*?</script>', re.IGNORECASE),
        re.compile(r'<.*?javascript:.*?>', re.IGNORECASE),
        re.compile(r'<.*?vbscript:.*?>', re.IGNORECASE),
        re.compile(r'<.*?expression.*?>', re.IGNORECASE)
    ]
    for pattern in unsafe_patterns:
        if pattern.search(plaintext):
            return False
    return True
